function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'CombinationIterator' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with CombinationIterator(characters, combinationLength).';
  const [characters, k] = args[0];
  if (typeof characters !== 'string' || characters.length < 1 || characters.length > 15) return 'characters has 1 to 15 letters.';
  if (!/^[a-z]+$/.test(characters)) return 'characters uses lowercase English letters only.';
  for (let i = 1; i < characters.length; i++) if (characters[i - 1] >= characters[i]) return 'characters must be distinct letters in sorted order.';
  if (!Number.isInteger(k) || k < 1 || k > characters.length) return 'combinationLength is from 1 to characters.length.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to next and hasNext.';
  let left = 1;
  for (let i = 0; i < k; i++) left = left * (characters.length - i) / (i + 1);
  left = Math.round(left);
  for (let i = 1; i < operations.length; i++) {
    if (!Array.isArray(args[i]) || args[i].length !== 0) return 'next and hasNext take no arguments.';
    if (operations[i] === 'next') {
      if (left === 0) return 'next is only called while a combination remains.';
      left--;
    } else if (operations[i] !== 'hasNext') {
      return 'Only next and hasNext can follow the constructor.';
    }
  }
  return null;
}

