class CombinationIterator {
  constructor(characters, combinationLength) {
    this.combinations = [];
    this.position = 0;
    const picked = [];
    const build = (start) => {
      if (picked.length === combinationLength) {
        this.combinations.push(picked.join(''));
        return;
      }
      const lastStart = characters.length - (combinationLength - picked.length);
      for (let i = start; i <= lastStart; i++) {
        picked.push(characters[i]);
        build(i + 1);
        picked.pop();
      }
    };
    build(0);
  }

  next() {
    const combination = this.combinations[this.position];
    this.position++;
    return combination;
  }

  hasNext() {
    return this.position < this.combinations.length;
  }
}

