class CombinationIterator {
  constructor(characters, combinationLength) {
    const all = [];
    for (let mask = 0; mask < (1 << characters.length); mask++) {
      let text = '';
      for (let bit = 0; bit < characters.length; bit++) if (mask & (1 << bit)) text += characters[bit];
      if (text.length === combinationLength) all.push(text);
    }
    all.sort();
    this.queue = all;
  }
  next() {
    return this.queue.shift();
  }
  hasNext() {
    return this.queue.length > 0;
  }
}

