function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(8, 15) : int(1, 6);
  const k = large && rand() < 0.5 ? int(Math.max(1, (n >> 1) - 2), Math.min(n, (n >> 1) + 2)) : int(1, n);
  const letters = 'abcdefghijklmnopqrstuvwxyz'.split('');
  for (let i = letters.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  const characters = letters.slice(0, n).sort().join('');
  let total = 1;
  for (let i = 0; i < k; i++) total = total * (n - i) / (i + 1);
  total = Math.round(total);
  const calls = large ? 499 : int(1, 12);
  const nextRate = 0.3 + rand() * 0.6;
  const operations = ['CombinationIterator'];
  const args = [[characters, k]];
  let left = total;
  for (let i = 0; i < calls; i++) {
    if (left > 0 && rand() < nextRate) {
      operations.push('next');
      left--;
    } else {
      operations.push('hasNext');
    }
    args.push([]);
  }
  return [operations, args];
}
